/* The JVM signature of the static body that a trait's springboard holds, self first. */
private String staticBodySig(scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m) {
    Functional fnl = m._1();
    StaticTypeReplacer inst = m._2();
    TraitType declaring = m._3();
    IdOrOp name = (IdOrOp) fnl.name();
    Type ret = fnl.getReturnType().unwrap();
    Type params = NodeUtil.getParamType(fnl.parameters(), NodeUtil.getSpan(name));
    if (inst != null) {
        ret = inst.replaceIn(ret);
        params = inst.replaceIn(params);
    }
    String sig = NamingCzar.jvmSignatureFor(params,
            NamingCzar.jvmBoxedTypeDesc(ret, component.getName()), 0, declaring, component.getName());
    int selfIndex = ((HasSelfType) fnl).selfPosition();
    if (selfIndex != Naming.NO_SELF)
        sig = Naming.removeNthSigParameter(sig, selfIndex + 1);
    return sig;
}

/*
 * Emits the static call of the body that trait t gives the method named name,
 * declared in t or inherited by it, for a call whose parameters other than self
 * have the JVM signature callParams; self and the arguments are on the stack, self first.
 * Answers false, emitting nothing, where t gives the method no body.
 */
private boolean emitBodyGivenBy(ASTNode x, TraitType t, IdOrOp name, int selfIndex, String callParams) {
    List<scala.Tuple3<Functional, StaticTypeReplacer, TraitType>> found =
        new ArrayList<scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>();
    boolean anyBody = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m : methodsNamed(t, name, selfIndex)) {
        if (!m._1().body().isSome()) continue;
        anyBody = true;
        String sig = staticBodySig(m);
        if (sigParams(Naming.removeNthSigParameter(sig, 0)).equals(callParams))
            found.add(m);
    }
    if (found.isEmpty()) {
        if (anyBody)
            throw sayWhat(x, "Can't find the body that " + t + " gives " + name.getText() + " at " + callParams);
        return false;
    }
    /* The most specific body: the one whose trait lies below every other's. */
    scala.Tuple3<Functional, StaticTypeReplacer, TraitType> best = found.get(0);
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m : found)
        if (typeAnalyzer.lteq(m._3(), best._3())) best = m;
    String owner = NamingCzar.jvmTypeDescAsTrait(best._3(), component.getName()) + NamingCzar.springBoard;
    String mname = Naming.fmDottedName(singleName(best._1().name()), selfIndex);
    addLineNumberInfo(x);
    mv.visitMethodInsn(INVOKESTATIC, owner, mname, staticBodySig(best));
    return true;
}

/* Whether trait t has more than one method named name at self position selfIndex. */
private boolean methodIsOverloaded(TraitType t, IdOrOp name, int selfIndex) {
    return methodsNamed(t, name, selfIndex).size() > 1;
}

/*
 * A dotted call whose receiver is an assumption, (e asif T).m(args): the body that T
 * gives m, called with the value as self.  Answers false where it emits nothing.
 */
private boolean assumedReceiverCall(MethodInvocation x, AsIfExpr obj, Type domain_type, Type range_type) {
    TraitType t = assumedTrait(obj);
    if (t == null) return false;
    IdOrOp method = x.getMethod();
    List<Expr> args = callArgList(x.getArg());
    if (assumptionCount(args) != args.size() && methodIsOverloaded(t, method, Naming.NO_SELF))
        throw sayWhat(x, ASSUMPTION_PARTIAL_CALL);
    String callParams = sigParams(NamingCzar.jvmSignatureFor(domain_type, range_type, thisApi()));
    boolean hasBody = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m : methodsNamed(t, method, Naming.NO_SELF))
        if (m._1().body().isSome()) hasBody = true;
    if (!hasBody) return false;
    obj.accept(this);
    evalArg(x, domain_type, x.getArg());
    return emitBodyGivenBy(x, t, method, Naming.NO_SELF, callParams);
}

/*
 * A call of a function or functional method with an assumption among its arguments,
 * whose arguments are on the stack.  Answers true where it emitted the call.
 */
private boolean assumedArgumentsCall(FunctionalRef x, ArrowType arrow, String pkgClass, String theFunction,
                                     List<Expr> args, boolean generic) {
    int assumed = assumptionCount(args);

}

/*
 * Whether the generic method that a dotted call names, with nsargs static arguments, at the
 * tuple domain_type, declares one parameter: a generic declaration of the name that the
 * receiver's type holds with nsargs static parameters declares one, and none declares a
 * parameter for each of the tuple's elements.  A declaration of another number of
 * parameters cannot take the call.
 */
private boolean genericMethodTakesOneParameter(Type receiverType, IdOrOp method, int nsargs,
                                               Type domain_type) {
    if (!(domain_type instanceof TupleType) || NodeUtil.isVoidType(domain_type)) return false;
    if (!(receiverType instanceof TraitType)) return false;
    int n = ((TupleType) domain_type).getElements().size();
    boolean one = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m :
             methodsNamed((TraitType) receiverType, method, Naming.NO_SELF)) {
        Functional fnl = m._1();
        if (fnl.staticParameters().size() != nsargs) continue;
        int k = fnl.parameters().size();
        if (k == 1) one = true;
        else if (k == n) return false;
    }
    return one;
}

/*
 * Whether a dotted call of the method on a receiver of the type t, at the tuple domain_type,
 * passes its argument as one value: each declaration of the method that t holds and that
 * can take the tuple takes it so (paramTypeAtInstance), as a declaration over a type
 * parameter does where t makes it the tuple.  A declaration that takes the tuple's elements,
 * by one parameter of a tuple type or by one parameter for each, keeps them separate.
 */
private boolean callTakesTupleBoxed(TraitType t, IdOrOp method, Type domain_type) {
    if (!(domain_type instanceof TupleType) || NodeUtil.isVoidType(domain_type)) return false;
    int n = ((TupleType) domain_type).getElements().size();
    /* The replacer of a declaration that t's own trait makes holds no static argument
     * of t; this one gives them. */
    StaticTypeReplacer own = null;
    Option<TypeConsIndex> oti = typeAnalyzer.traits().typeCons(t.getName());
    if (!t.getArgs().isEmpty() && oti.isSome() && oti.unwrap() instanceof TraitIndex &&
        ((TraitIndex) oti.unwrap()).staticParameters().size() == t.getArgs().size())
        own = new StaticTypeReplacer(((TraitIndex) oti.unwrap()).staticParameters(), t.getArgs());
    boolean boxed = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m :
             methodsNamed(t, method, Naming.NO_SELF)) {
        Functional fnl = m._1();
        if (!fnl.staticParameters().isEmpty() || m._2() == null) continue;
        Type declared = NodeUtil.getParamType(fnl.parameters(), NodeUtil.getSpan(method));
        Type instance = m._2().replaceIn(declared);
        if (own != null) instance = own.replaceIn(instance);
        Type at = paramTypeAtInstance(declared, instance);
        if (takesTupleBoxed(at)) {
            if (((TupleType) ((TupleType) at).getElements().get(0)).getElements().size() == n)
                boxed = true;
        } else if (at instanceof TupleType && ((TupleType) at).getElements().size() == n)
            return false;
    }
    return boxed;
}

/* The argument of a call, of the tuple type domain_type, as one value. */
private void pushTupleBoxed(Expr arg, Type domain_type) {
    arg.accept(this);
    conditionallyCastParameter(arg, domain_type);
    paramCount = 1;
}

private Type sanitizePossibleStupidIntersectionType(Type receiverType) {
    if (receiverType instanceof TraitSelfType) {
        receiverType = ((TraitSelfType) receiverType).getNamed();
    }
    if (receiverType instanceof NamedType)
        return receiverType;
    if (receiverType instanceof IntersectionType) {
        IntersectionType it = (IntersectionType) receiverType;
        Type at = null;
        for (Type t : it.getElements()) {
                t = sanitizePossibleStupidIntersectionType(t);
                if (at == null)
                    at = t;
                else {
                    CFormula c1 = typeAnalyzer.subtype(t, at);
                    CFormula c2 = typeAnalyzer.subtype(at, t);
                    if (Formula.isTrue(c1, typeAnalyzer)) {
                        at = t;
                    } else if (Formula.isTrue(c2, typeAnalyzer)) {
                        // at is subtype, do nothing.
                    } else {
                        return receiverType;
                    }

                }

        }
        return at;
    }
    return receiverType;
}

/*
 * The trait to which a dotted call casts a receiver whose static type is an
 * intersection that none of its conjuncts lies below, as a call typed by the
 * intersection of its candidates' return types is: the conjunct that declares or
 * inherits the called method, the most specific where several do.  The checker
 * finds the method among the methods of the conjuncts that are trait types; where
 * its arrow names the trait that declares the method, only the conjuncts that have
 * that declaration qualify, so that the JVM finds the method at the call's
 * signature; where the call has no arrow, as a getter's, only the conjuncts with a
 * method of the name that takes the call's argument qualify.  Of several conjuncts
 * that neither lies below the other, each has that declaration and the object's
 * class runs its own: the first is taken.
 */
private TraitType intersectionMethodOwner(ASTNode x, IntersectionType it, IdOrOp method,
                                          Option<Type> overloadingType, Type domain) {
    List<TraitType> conjuncts = new ArrayList<TraitType>();
    traitConjuncts(it, conjuncts);
    Id declaring = null;
    if (overloadingType.isSome() && overloadingType.unwrap() instanceof ArrowType) {
        Option<MethodInfo> omi = ((ArrowType) overloadingType.unwrap()).getMethodInfo();
        if (omi.isSome()) {
            Type self = omi.unwrap().getSelfType();
            if (self instanceof TraitSelfType) self = ((TraitSelfType) self).getNamed();
