import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;
// JfrTop <file.jfr> [n] [filter]: execution samples by self frame and inclusive method; filter counts samples whose stack holds the text.
public class JfrTop {
    public static void main(String[] a) throws Exception {
        int n = a.length > 1 ? Integer.parseInt(a[1]) : 25;
        String filter = a.length > 2 ? a[2] : null;
        Map<String, Integer> self = new HashMap<>(), incl = new HashMap<>();
        int total = 0, filtered = 0;
        try (RecordingFile rf = new RecordingFile(Paths.get(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null || st.getFrames().isEmpty()) continue;
                total++;
                List<RecordedFrame> fs = st.getFrames();
                String top = name(fs.get(0));
                self.merge(top, 1, Integer::sum);
                Set<String> seen = new HashSet<>();
                boolean hit = false;
                for (RecordedFrame f : fs) { String m = name(f); if (seen.add(m)) incl.merge(m, 1, Integer::sum); if (filter != null && m.contains(filter)) hit = true; }
                if (hit) filtered++;
            }
        }
        System.out.println("samples " + total + (filter != null ? ("; with " + filter + " on the stack: " + filtered) : ""));
        System.out.println("-- self"); print(self, n, total);
        System.out.println("-- inclusive (com.sun.fortress only)");
        Map<String, Integer> f2 = new HashMap<>(); for (var e : incl.entrySet()) if (e.getKey().startsWith("com.sun.fortress")) f2.put(e.getKey(), e.getValue());
        print(f2, n, total);
    }
    static String name(RecordedFrame f) { RecordedMethod m = f.getMethod(); return m.getType().getName() + "." + m.getName(); }
    static void print(Map<String, Integer> m, int n, int total) {
        m.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(n)
         .forEach(e -> System.out.printf("%6d %5.1f%% %s%n", e.getValue(), 100.0 * e.getValue() / total, e.getKey()));
    }
}
EOF
